// The runtime's own statement of what it puts on the HTTP wire, so checking a consumer for
// drift is a diff rather than a reading exercise. Two artifacts, both generated by
// `http-wire.test.ts` and both committed: the fixture (real responses from the real handlers,
// one entry per case) and the constraints (the closed vocabularies and caps, read straight out
// of the modules that own them). Nothing here is hand-written.
import { fileURLToPath } from "node:url";
import {
  DEFAULT_BODY_LIMIT_BYTES,
  MAX_ANSWER_CHARS,
  MAX_CHECKPOINT_BUNDLE_BYTES,
  MAX_DOCUMENTS_PER_RUN,
  MAX_FILES_LISTING_BYTES,
  MAX_OUTPUT_FORMAT_CHARS,
  MAX_PROMPT_CHARS,
  MAX_PUBLISHED_OUT_FILES,
  MAX_RECARRIED_OUT_FILES,
  MAX_RECARRIED_OUT_PATH_CHARS,
  MAX_RUN_TOKEN_CHARS,
  MAX_SKILL_ASSETS_PER_SKILL,
  MAX_SKILL_DESCRIPTION_CHARS,
  MAX_SYSTEM_PROMPT_CHARS,
  MAX_TOTAL_DOCUMENT_BYTES,
  RETAINED_OUTPUT_WORST_CASE_BYTES,
  RUN_BUDGET_CEILING_USD,
  RUN_DEADLINE_CEILING_MS,
  RUN_INPUT_BODY_LIMIT_BYTES,
  RUN_TURNS_CEILING,
} from "../config.js";
import { CAPACITY_REASONS } from "../http-transport.js";
import { CHECKPOINT_SHA256_HEADER } from "../run-files-routes.js";
import { DEFAULT_PAUSE_TTL_MS } from "../run-orchestrator.js";
import {
  RETENTION_MS,
  RETRYABLE_FAILURE_SUBTYPES,
  RUN_STATUSES,
  type RunStatus,
  TERMINAL_STATUSES,
} from "../run-registry.js";
import { RUNTIME_FAILURE_SUBTYPES } from "../run-report.js";
import { EXECUTION_ID_PATTERN } from "../safe-path.js";
import { CONFLICT_CODES, monitorPollHeaders } from "../server.js";

export const WIRE_FIXTURE_PATH = fileURLToPath(new URL("http-wire.fixture.json", import.meta.url));
export const WIRE_CONSTRAINTS_PATH = fileURLToPath(new URL("http-wire.constraints.json", import.meta.url));

// Set to regenerate both artifacts. The run that writes them always fails, so an accidental
// regeneration can never be mistaken for a green gate.
export const UPDATE_FIXTURES_ENV = "UPDATE_WIRE_FIXTURES";

// The response headers a consumer has to act on. `date` and the hop-by-hop noise are excluded;
// everything here is either a routing signal or a safety header the client must not lose.
export const CONTRACT_HEADER_NAMES: readonly string[] = [
  "allow",
  "connection",
  "content-disposition",
  "content-length",
  "content-type",
  "retry-after",
  "www-authenticate",
  CHECKPOINT_SHA256_HEADER,
  "x-content-type-options",
];

export type WireRequest = {
  method: string;
  path: string;
  auth?: string;
  contentType?: string;
  body?: unknown;
};

export type WireResponse = {
  status: number;
  headers: Record<string, string>;
  body: unknown;
};

export type WireExchange = {
  request: WireRequest;
  // Present only where a cap has to be scaled down to be reachable in a test — the numbers in
  // the captured body are that configuration's, and the production values live in the
  // constraints file. Absent means the case ran on the production-shaped config.
  configOverrides?: Record<string, number>;
  response: WireResponse;
};

export const RESUME_TOKEN_PLACEHOLDER = "<UUID>";

// Resume tokens are the one genuinely non-deterministic value on the wire — every other volatile
// input (clock, jitter, ports) is an injected seam the capture pins. Substitution is by exact
// value, not by shape, so a token the capture invented stays distinguishable in the fixture from
// a well-formed one the case deliberately made up.
export function normalizeWireValue(value: unknown, minted: ReadonlySet<string>): unknown {
  if (typeof value === "string") {
    return minted.has(value) ? RESUME_TOKEN_PLACEHOLDER : value;
  }
  if (Array.isArray(value)) {
    return value.map((entry) => normalizeWireValue(entry, minted));
  }
  if (typeof value === "object" && value !== null) {
    return Object.fromEntries(
      Object.entries(value).map(([key, entry]) => [key, normalizeWireValue(entry, minted)]),
    );
  }
  return value;
}

export function contractHeadersOf(headers: Headers): Record<string, string> {
  const captured: Record<string, string> = {};
  for (const name of CONTRACT_HEADER_NAMES) {
    const value = headers.get(name);
    if (value !== null) {
      captured[name] = value;
    }
  }
  return captured;
}

// Every field reads from the module that owns the fact, so a change there lands in the diff
// without anyone remembering to mirror it.
export function buildWireConstraints(httpStatuses: readonly number[]): Record<string, unknown> {
  return {
    executionId: { pattern: EXECUTION_ID_PATTERN.source },
    httpStatuses: [...httpStatuses].sort((a, b) => a - b),
    runStatuses: [...RUN_STATUSES].sort(),
    terminalStatuses: [...TERMINAL_STATUSES].sort(),
    retryAfterSeconds: Object.fromEntries(
      [...RUN_STATUSES]
        .sort()
        .map((status: RunStatus) => [status, monitorPollHeaders(status)["retry-after"] ?? null]),
    ),
    failureSubtypes: {
      // Closed: `http-wire.test.ts` scans the sources and fails if a subtype literal escapes it.
      runtimeOriginated: [...RUNTIME_FAILURE_SUBTYPES].sort(),
      // Open: an SDK result subtype the runtime does not recognise rides through verbatim, so a
      // consumer must treat any unlisted subtype as a generic failure rather than reject it.
      sdkSubtypesPassThrough: true,
    },
    retryableFailureSubtypes: [...RETRYABLE_FAILURE_SUBTYPES].sort(),
    conflictCodes: [...CONFLICT_CODES].sort(),
    capacityReasons: [...CAPACITY_REASONS].sort(),
    retentionMs: RETENTION_MS,
    pauseTtlMs: DEFAULT_PAUSE_TTL_MS,
    caps: {
      maxRequestBodyBytes: DEFAULT_BODY_LIMIT_BYTES,
      maxRunInputBodyBytes: RUN_INPUT_BODY_LIMIT_BYTES,
      maxTotalDocumentBytes: MAX_TOTAL_DOCUMENT_BYTES,
      maxDocumentsPerRun: MAX_DOCUMENTS_PER_RUN,
      maxPromptChars: MAX_PROMPT_CHARS,
      maxAnswerChars: MAX_ANSWER_CHARS,
      maxSystemPromptChars: MAX_SYSTEM_PROMPT_CHARS,
      maxOutputFormatChars: MAX_OUTPUT_FORMAT_CHARS,
      maxRunTokenChars: MAX_RUN_TOKEN_CHARS,
      maxSkillAssetsPerSkill: MAX_SKILL_ASSETS_PER_SKILL,
      maxSkillDescriptionChars: MAX_SKILL_DESCRIPTION_CHARS,
      maxPublishedOutFiles: MAX_PUBLISHED_OUT_FILES,
      maxFilesListingBytes: MAX_FILES_LISTING_BYTES,
      maxCheckpointBundleBytes: MAX_CHECKPOINT_BUNDLE_BYTES,
      maxRecarriedOutFiles: MAX_RECARRIED_OUT_FILES,
      maxRecarriedOutPathChars: MAX_RECARRIED_OUT_PATH_CHARS,
    },
    fuseCeilings: {
      deadlineMs: RUN_DEADLINE_CEILING_MS,
      maxBudgetUsd: RUN_BUDGET_CEILING_USD,
      maxTurns: RUN_TURNS_CEILING,
      maxRetainedOutputBytes: RETAINED_OUTPUT_WORST_CASE_BYTES,
    },
  };
}

// Reaching this one needs a manifest over MAX_FILES_LISTING_BYTES, which is a module constant
// rather than a config knob, so no case can produce its body. Named here so the coverage check
// treats it as a deliberate exemption instead of a hole nobody noticed.
export const UNRECORDED_CAPACITY_REASONS: readonly string[] = ["files_listing_bytes"];

export function renderContractJson(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}
